   "id": "z7b0bfa53",
   "sez": "italia",
   "titolo": "Cortei nel Nord Italia: 28 arresti, 12 dei quali minorenni, e 141 agenti feriti",
   "orig": "Undicimila manifestanti, 28 arresti (12 minorenni) e 141 agenti feriti: il bollettino delle piazze",
   "lead": "Gli investigatori hanno tracciato un primo bilancio, ancora provvisorio, delle manifestazioni che sabato 17 ottobre hanno attraversato diverse città del Nord Italia. Nelle piazze sono scese circa undicimila persone. Le forze dell'ordine contano 28 arresti, di cui 12 riguardano minorenni, e 141 agenti rimasti feriti. Secondo quanto riportato, le persone identificate sono 197. I cortei, promossi sotto la sigla «Italia in piazza», sono degenerati in episodi descritti come guerriglia urbana. Il conteggio potrebbe ancora cambiare nelle prossime ore, man mano che gli accertamenti procedono.",
