   "titolo": "Schlein: alle elezioni si decide il futuro dell'Ue",
   "orig": "Schlein, con elezioni in gioco futuro Ue",
   "lead": "La segretaria del Partito democratico Elly Schlein sostiene che con le prossime elezioni sia in gioco il futuro dell'Unione europea. Ha parlato anche delle proteste degli ultimi giorni. Secondo Schlein, le violenze di alcuni non devono essere usate per oscurare la voce di chi manifesta in modo pacifico. Lo riferisce Rai News.",
