   "id": "z7e018b17",
   "sez": "prima",
   "titolo": "Francia, scontri in tutto il Paese tra studenti, sindacati e gilet gialli",
   "orig": "France: Protesters clash with police in nationwide protests, amid rising social polarization",
   "lead": "Sabato in molte città della Francia studenti, sindacalisti e militanti dei gilet gialli sono scesi in piazza contro il carovita e le disuguaglianze. In diverse zone le manifestazioni sono sfociate in scontri con la polizia, con scene di caos e incendi. Le forze dell'ordine hanno arrestato più di mille persone. La protesta era nata dalla scuola, ma si è trasformata in una crisi politica più ampia, che fa emergere una rabbia profonda per il tenore di vita e una crescente polarizzazione sociale.",
   "more": [
    "Il movimento dei gilet gialli è nato in Francia nel 2018 come protesta contro il rincaro dei carburanti. Si è poi allargato a rivendicazioni più generali sul potere d'acquisto e sulla giustizia sociale."
   ],
