   "id": "z65fe7742",
   "sez": "cucina",
   "titolo": "Kopi luwak, il caffè da mille dollari al chilo e il prezzo pagato dagli zibetti",
   "orig": "Il caffè che costa fino a 1.000 dollari al chilo si produce con gli escrementi di un animale. E nasconde una storia di sfruttamento",
   "lead": "Il kopi luwak è un caffè che può costare fino a mille dollari al chilo. Si ottiene da chicchi che gli zibetti mangiano ed espellono. La forte domanda internazionale ha però alimentato la diffusione di allevamenti in gabbia, con gravi problemi di benessere per gli animali. Dietro il prodotto di lusso si nasconde quindi una storia di sfruttamento. Lo riferisce Gambero Rosso.",
   "more": [
    "Il kopi luwak è legato soprattutto all'Indonesia. In origine i chicchi venivano raccolti dagli escrementi degli zibetti selvatici; la richiesta crescente ha poi spinto molti produttori a tenere gli animali in cattività."
   ],
