   "sez": "sport",
   "titolo": "Serie A, il Como vince 3-1 in casa della Fiorentina",
   "orig": "Serie A: Fiorentina-Como 1-3 DIRETTA",
   "lead": "Nella partita di Serie A tra Fiorentina e Como, la squadra lombarda si è imposta per 3-1 sul campo dei viola, conquistando una vittoria in trasferta. Il risultato segna un pomeriggio difficile per la Fiorentina davanti al proprio pubblico. Le fonti disponibili riportano soltanto il punteggio finale, senza indicare i marcatori né lo svolgimento della gara, raccontata con cronaca e immagini. Lo riferisce ANSA.",
