   "sez": "viaggi",
   "titolo": "Viaggi nel 2027, nove tendenze per continuare a desiderare di partire",
   "orig": "Partire nel 2027, nove tendenze chiave per non smettere di desiderare viaggi nonostante tutto",
   "lead": "Uno studio di previsioni sul turismo, le «Travel Predictions», individua nove tendenze chiave per i viaggi del 2027. L'analisi descrive nuovi modi di partire che mantengono vivo il desiderio di viaggiare nonostante le difficoltà del momento. Tra i temi indicati ci sono il valore sociale del viaggio e la riconciliazione. Le fonti non forniscono ulteriori dettagli sull'elenco completo delle tendenze né sull'autore della ricerca. Lo riferisce ANSA.",
