   "id": "zed75d3c6",
   "sez": "musica",
   "titolo": "Israele, giovani virali mentre cantano la «Canzone per la pace»",
   "orig": "'They've been through enough shit': Young Israelis go viral singing 'Song for Peace'",
   "lead": "Centinaia di giovani israeliani hanno cantato la «Canzone per la pace», inno non ufficiale del movimento pacifista, al festival InDNegev, che per tradizione si chiude proprio con questo brano. Le immagini sono diventate virali in rete. La canzone è legata alla memoria di Yitzhak Rabin, che la cantò pochi minuti prima di essere assassinato nel 1995, consolidandone il posto nella sua eredità. Lo riferisce Haaretz.",
