   "sez": "adolescenti",
   "titolo": "Studente con BES bocciato alla maturità, il TAR respinge il ricorso",
   "orig": "Strumenti compensativi d’esame non obbligatori per studenti con BES, il TAR conferma la bocciatura e respinge il ricorso della famiglia",
   "lead": "Il Tribunale amministrativo regionale della Puglia ha respinto il ricorso di uno studente con Bisogni educativi speciali, che chiedeva di annullare l'esito negativo dell'Esame di Stato. Secondo quanto emerge, gli strumenti compensativi durante l'esame non erano obbligatori nel suo caso. Il TAR ha quindi confermato la bocciatura, dando torto alla famiglia che aveva presentato il ricorso. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Gli studenti con Bisogni educativi speciali (BES) possono avere un piano didattico personalizzato con strumenti compensativi, come mappe concettuali o calcolatrici, e misure dispensative. Il TAR è il giudice amministrativo di primo grado, competente anche sugli atti delle scuole come gli esiti degli esami."
   ],
