   "sez": "economia",
   "titolo": "Protesta dei Tir, martedì il tavolo sull'autotrasporto: Salvini pronto a sbloccare i fondi",
   "orig": "Protesta Tir, martedì il tavolo sull’autotrasporto. Salvini pronto a sbloccare le risorse",
   "lead": "Dopo la protesta degli autotrasportatori, martedì si terrà un tavolo sul settore. Il ministro Matteo Salvini è pronto a sbloccare le risorse attese dalla categoria. Il ministero sta lavorando per rendere disponibili 590 milioni di euro destinati al rinnovo dei mezzi pesanti. Si valuta anche di estendere il credito d'imposta sul gasolio, uno dei temi più cari alle imprese di trasporto. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "In Italia gran parte delle merci viaggia su gomma. Per questo il costo del carburante incide molto sui bilanci delle imprese di autotrasporto. Il rinnovo dei mezzi serve anche a ridurre le emissioni inquinanti."
   ],
