   "orig": "Hoima Teacher Wins Omumanyi wa Salam TV Bunyoro-Tooro Finals",
   "lead": "Turamyomu Kautharah, un'insegnante di Hoima, ha vinto la finale per la regione di Bunyoro-Tooro della settima edizione di Omumanyi wa Salam TV. Si tratta di un concorso televisivo ugandese. Grazie a questa vittoria rappresenterà la sua regione nella finalissima nazionale, in programma il 19 dicembre a Kampala. Lì sfiderà i vincitori delle altre aree del Paese. Lo riferisce Nile Post.",
