   "lead": "Dopo lo spettacolare primo successo nel Test contro il Sudafrica, l'Australia punta a costruire sulla vittoria a Gqeberha, nell'Eastern Cape, dove la serie si sposta. La partita riparte dopo una pausa per la pioggia, con l'attacco di velocisti schierato per la giornata. La diretta segue tutte le azioni. Lo riferisce ABC News Australia.",
